{"function":"() => {
function parse(c){const m=c.match(/[\d.]+/g).map(Number);return {r:m[0],g:m[1],b:m[2],a:m[3]===undefined?1:m[3]};}
function lum({r,g,b}){return [r,g,b].map(v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)}).reduce((s,v,i)=>s+v*[0.2126,0.7152,0.0722][i],0);}
function bg(el){let e=el;while(e){const c=parse(getComputedStyle(e).backgroundColor);if(c.a>0.5)return c;e=e.parentElement||e.getRootNode().host;}return {r:255,g:255,b:255,a:1};}
function cr(el){const s=getComputedStyle(el);const f=parse(s.color),b=bg(el);const l1=lum(f),l2=lum(b);return {color:s.color,bg:`rgb(${b.r},${b.g},${b.b})`,ratio:+((Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05)).toFixed(2),fs:s.fontSize,fw:s.fontWeight};}
const o={};
const chipText=[...document.querySelectorAll('.br-tag.interaction span.text-gray-50')];
o.chip = chipText.map(cr).slice(0,1);
o.chipBorder = getComputedStyle(document.querySelector('.br-tag.interaction')).borderColor;
o.status = cr(document.querySelector('pnip-status-solicitacao-utils .text-secondary-01'));
o.dateTag = cr(document.querySelector('.br-tag.primary-pastel-01'));
o.th = cr(document.querySelector('table thead th'));
o.td = cr(document.querySelector('table tbody td'));
o.h2 = cr(document.querySelector('h2'));
o.tabs = [...document.querySelectorAll('nav.tab-nav button')].map(b=>({t:b.textContent.trim(), ...cr(b.querySelector('.name')||b), border:getComputedStyle(b).borderBottom, liBorder:getComputedStyle(b.parentElement).borderBottom, liAfter:getComputedStyle(b.parentElement,'::after').borderBottom}));
o.pagActive = cr(document.querySelector('a.page.active'));
o.pag = cr(document.querySelectorAll('a.page')[1]);
const upd=[...document.querySelectorAll('div')].find(e=>/^Última atualização/.test(e.textContent.trim()));
o.upd = upd && {html:upd.outerHTML.slice(0,400), ...cr(upd)};
o.avatarPerfil = cr(document.querySelector('.dropdown-user-perfil'));
o.avatarName = cr(document.querySelector('.br-sign-in .text-gray-80'));
const h=document.querySelector('br-header').shadowRoot;
o.headerTitle=cr(h.querySelector('.header-title'));
o.headerSign=cr(h.querySelector('.header-sign'));
o.crumb = cr(document.querySelector('br-breadcrumb').shadowRoot.querySelector('[data-active] span'));
o.dateLabel = cr([...document.querySelectorAll('span.text-bold')].find(s=>s.textContent.includes('Data da')));
return o;}"}

